// func encodeBetterBlockAsm(dst []byte, src []byte, tmp *[589824]byte) int
// Requires: BMI, SSE2
TEXT ·encodeBetterBlockAsm(SB), $24-64
	MOVD tmp+48(FP), R0
	MOVD dst_base+0(FP), R1
	MOVD $0x00001200, R2
	MOVD R0, R3
	VEOR V0.B16, V0.B16, V0.B16

zero_loop_encodeBetterBlockAsm:
	FMOVQ F0, (R3)
	FMOVQ F0, 16(R3)
	FMOVQ F0, 32(R3)
	FMOVQ F0, 48(R3)
	FMOVQ F0, 64(R3)
	FMOVQ F0, 80(R3)
	FMOVQ F0, 96(R3)
	FMOVQ F0, 112(R3)
	ADD   $0x80, R3, R3
	SUBS  $1, R2, R2
	BNE   zero_loop_encodeBetterBlockAsm
	MOVD  $0x00000000, R16
	MOVW  R16, 20(RSP)
	MOVD  src_len+32(FP), R2
	SUB   $6, R2, R3
	SUB   $8, R2, R5
	MOVW  R5, 16(RSP)
	LSR   $0x05, R2, R2
	SUBW  R2, R3, R3
	ADD   R3, R1, R3
	MOVD  R3, 8(RSP)
	MOVD  $0x00000001, R2
	MOVD  $0x00000000, R16
	MOVW  R16, 24(RSP)
	MOVD  src_base+24(FP), R3

search_loop_encodeBetterBlockAsm:
	MOVWU R2, R5
	MOVWU 20(RSP), R16
	SUBW  R16, R5, R5
	LSRW  $0x07, R5, R5
	CMPW  $0x63, R5
	BLS   check_maxskip_ok_encodeBetterBlockAsm
	ADD   $100, R2, R5
	MOVWU R5, R5
	JMP   check_maxskip_cont_encodeBetterBlockAsm

check_maxskip_ok_encodeBetterBlockAsm:
	ADD   R5, R2, R5
	ADD   $1, R5, R5
	MOVWU R5, R5

check_maxskip_cont_encodeBetterBlockAsm:
	MOVWU 16(RSP), R16
	CMPW  R16, R5
	BHS   emit_remainder_encodeBetterBlockAsm
	MOVD  (R3)(R2), R6
	MOVW  R5, 28(RSP)
	MOVD  $0x00cf1bbcdcbfa563, R8
	MOVD  $0x9e3779b1, R5
	MOVD  R6, R9
	MOVD  R6, R10
	LSL   $0x08, R9, R9
	MUL   R8, R9, R9
	LSR   $0x2f, R9, R9
	LSL   $0x20, R10, R10
	MUL   R5, R10, R10
	LSR   $0x32, R10, R10
	MOVWU (R0)(R9<<2), R5
	ADD   R10<<2, R0, R15
	MOVWU 524288(R15), R7
	MOVW  R2, (R0)(R9<<2)
	ADD   R10<<2, R0, R15
	MOVW  R2, 524288(R15)
	MOVD  (R3)(R5), R9
	MOVD  (R3)(R7), R10
	CMP   R6, R9
	BEQ   candidate_match_encodeBetterBlockAsm
	CMP   R6, R10
	BNE   no_short_found_encodeBetterBlockAsm
	MOVWU R7, R5
	JMP   candidate_match_encodeBetterBlockAsm

