// func matchLen(a []byte, b []byte) int
// Requires: BMI
TEXT ·matchLen(SB), NOSPLIT, $0-56
	MOVD a_base+0(FP), R0
	MOVD b_base+24(FP), R1
	MOVD a_len+8(FP), R2

	// matchLen
	MOVD $0, R5

matchlen_loopback_16_standalone:
	CMPW  $0x10, R2
	BLO   matchlen_match8_standalone
	MOVD  (R0)(R5), R3
	ADD   R5, R0, R15
	MOVD  8(R15), R6
	MOVD  (R1)(R5), R16
	EOR   R16, R3, R3
	TST   R3, R3
	BNE   matchlen_bsf_8_standalone
	ADD   R5, R1, R15
	MOVD  8(R15), R16
	EOR   R16, R6, R6
	TST   R6, R6
	BNE   matchlen_bsf_16standalone
	SUB   $16, R2, R2
	MOVWU R2, R2
	ADD   $16, R5, R5
	MOVWU R5, R5
	JMP   matchlen_loopback_16_standalone

matchlen_bsf_16standalone:
	RBIT  R6, R6
	CLZ   R6, R6
	ASR   $0x03, R6, R6
	ADD   R6, R5, R5
	ADD   $8, R5, R5
	MOVWU R5, R5
	JMP   gen_match_len_end

matchlen_match8_standalone:
	CMPW  $0x08, R2
	BLO   matchlen_match4_standalone
	MOVD  (R0)(R5), R3
	MOVD  (R1)(R5), R16
	EOR   R16, R3, R3
	TST   R3, R3
	BNE   matchlen_bsf_8_standalone
	SUB   $8, R2, R2
	MOVWU R2, R2
	ADD   $8, R5, R5
	MOVWU R5, R5
	JMP   matchlen_match4_standalone

matchlen_bsf_8_standalone:
	RBIT  R3, R3
	CLZ   R3, R3
	ASR   $0x03, R3, R3
	ADD   R3, R5, R5
	MOVWU R5, R5
	JMP   gen_match_len_end

matchlen_match4_standalone:
	CMPW  $0x04, R2
	BLO   matchlen_match2_standalone
	MOVWU (R0)(R5), R3
	MOVWU (R1)(R5), R16
	CMPW  R3, R16
	BNE   matchlen_match2_standalone
	SUB   $4, R2, R2
	MOVWU R2, R2
	ADD   $4, R5, R5
	MOVWU R5, R5

matchlen_match2_standalone:
	CMPW  $0x01, R2
	BEQ   matchlen_match1_standalone
	BLO   gen_match_len_end
	MOVHU (R0)(R5), R16
	BFI   $0, R16, $16, R3
	ADD   R5, R1, R15
	MOVHU (R15), R15
	AND   $0xffff, R3, R16
	CMP   R16, R15
	BNE   matchlen_match1_standalone
	ADD   $2, R5, R5
	MOVWU R5, R5
	SUBSW $0x02, R2, R2
	BEQ   gen_match_len_end

matchlen_match1_standalone:
	MOVBU (R0)(R5), R16
	BFI   $0, R16, $8, R3
	ADD   R5, R1, R15
	MOVBU (R15), R15
	AND   $0xff, R3, R16
	CMP   R16, R15
	BNE   gen_match_len_end
	ADD   $1, R5, R5
	MOVWU R5, R5

gen_match_len_end:
	MOVD R5, ret+48(FP)
	RET

// func cvtLZ4BlockAsm(dst []byte, src []byte) (uncompressed int, dstUsed int)
// Requires: SSE2
TEXT ·cvtLZ4BlockAsm(SB), NOSPLIT, $0-64
	MOVD $0, R5
	MOVD dst_base+0(FP), R0
	MOVD dst_len+8(FP), R1
	MOVD src_base+24(FP), R2
	MOVD src_len+32(FP), R3
	ADD  R3, R2, R3
	ADD  R1, R0, R1
	SUB  $8, R1, R1
	MOVD $0, R6

lz4_s2_loop:
	CMP   R3, R2
	BHS   lz4_s2_corrupt
	CMP   R1, R0
	BHS   lz4_s2_dstfull
	MOVBU (R2), R7
	MOVD  R7, R8
	MOVD  R7, R9
	LSR   $0x04, R8, R8
	AND   $0x0f, R9, R9
	CMP   $0xf0, R7
	BLO   lz4_s2_ll_end

lz4_s2_ll_loop:
	ADD   $1, R2, R2
	CMP   R3, R2
	BHS   lz4_s2_corrupt
	MOVBU (R2), R7
	ADD   R7, R8, R8
	CMP   $0xff, R7
	BEQ   lz4_s2_ll_loop

lz4_s2_ll_end:
	ADD   R8, R2, R7
	ADD   $0x04, R9, R9
	CMP   R3, R7
	BHS   lz4_s2_corrupt
	ADD   $1, R2, R2
	ADD   $1, R7, R7
	TST   R8, R8
	BEQ   lz4_s2_lits_done
	ADD   R8, R0, R10
	CMP   R1, R10
	BHS   lz4_s2_dstfull
	ADD   R8, R5, R5
	SUB   $1, R8, R10
	MOVWU R10, R10
	CMPW  $0x3c, R10
