// func cvtLZ4sBlockAsm(dst []byte, src []byte) (uncompressed int, dstUsed int)
// Requires: SSE2
TEXT ·cvtLZ4sBlockAsm(SB), NOSPLIT, $0-64
	MOVD $0, R5
	MOVD dst_base+0(FP), R0
	MOVD dst_len+8(FP), R1
	MOVD src_base+24(FP), R2
	MOVD src_len+32(FP), R3
	ADD  R3, R2, R3
	ADD  R1, R0, R1
	SUB  $8, R1, R1
	MOVD $0, R6

lz4s_s2_loop:
	CMP   R3, R2
	BHS   lz4s_s2_corrupt
	CMP   R1, R0
	BHS   lz4s_s2_dstfull
	MOVBU (R2), R7
	MOVD  R7, R8
	MOVD  R7, R9
	LSR   $0x04, R8, R8
	AND   $0x0f, R9, R9
	CMP   $0xf0, R7
	BLO   lz4s_s2_ll_end

lz4s_s2_ll_loop:
	ADD   $1, R2, R2
	CMP   R3, R2
	BHS   lz4s_s2_corrupt
	MOVBU (R2), R7
	ADD   R7, R8, R8
	CMP   $0xff, R7
	BEQ   lz4s_s2_ll_loop

lz4s_s2_ll_end:
