	MOVWU R10, R10
	CMPW  $0x3c, R10
	BLO   one_byte_lz4s_s2
	CMPW  $0x00000100, R10
	BLO   two_bytes_lz4s_s2
	CMPW  $0x00010000, R10
	BLO   three_bytes_lz4s_s2
	CMPW  $0x01000000, R10
