	BHS   lz4_snappy_corrupt
	MOVHU (R2), R7
	MOVD  R6, R2
	TST   R7, R7
	BEQ   lz4_snappy_corrupt
	CMP   R5, R7
	BHI   lz4_snappy_corrupt
