	BNE   lz4_snappy_ml_done

lz4_snappy_ml_loop:
	MOVBU (R2), R6
	ADD   $1, R2, R2
	ADD   R6, R8, R8
	CMP   R3, R2
	BHS   lz4_snappy_corrupt
	CMP   $0xff, R6
	BEQ   lz4_snappy_ml_loop

lz4_snappy_ml_done:
	ADD R8, R5, R5

	// emitCopy
two_byte_offset_lz4_s2:
	CMPW  $0x40, R8
	BLS   two_byte_offset_short_lz4_s2
	MOVD  $0xee, R16
	MOVB  R16, (R0)
	MOVH  R7, 1(R0)
	SUB   $60, R8, R8
	MOVWU R8, R8
	ADD   $0x03, R0, R0
	CMP   R1, R0
	BHS   lz4_snappy_loop
	JMP   two_byte_offset_lz4_s2

two_byte_offset_short_lz4_s2:
	MOVWU R8, R6
	LSLW  $0x02, R6, R6
	CMPW  $0x0c, R8
	BHS   emit_copy_three_lz4_s2
	CMPW  $0x00000800, R7
	BHS   emit_copy_three_lz4_s2
	SUB   $15, R6, R6
	MOVWU R6, R6
	MOVB  R7, 1(R0)
	LSRW  $0x08, R7, R7
	LSLW  $0x05, R7, R7
	ORRW  R7, R6, R6
	MOVB  R6, (R0)
	ADD   $0x02, R0, R0
	JMP   lz4_snappy_loop

emit_copy_three_lz4_s2:
	SUB   $2, R6, R6
	MOVWU R6, R6
	MOVB  R6, (R0)
	MOVH  R7, 1(R0)
	ADD   $0x03, R0, R0
	JMP   lz4_snappy_loop

lz4_snappy_done:
	MOVD dst_base+0(FP), R1
	SUB  R1, R0, R0
	MOVD R5, uncompressed+48(FP)
	MOVD R0, dstUsed+56(FP)
	RET

lz4_snappy_corrupt:
	MOVD $0, R0
	SUB  $1, R0, R5
	MOVD R5, uncompressed+48(FP)
	RET

lz4_snappy_dstfull:
	MOVD $0, R0
	SUB  $2, R0, R5
	MOVD R5, uncompressed+48(FP)
	RET

// func cvtLZ4sBlockSnappyAsm(dst []byte, src []byte) (uncompressed int, dstUsed int)
// Requires: SSE2
TEXT ·cvtLZ4sBlockSnappyAsm(SB), NOSPLIT, $0-64
	MOVD $0, R5
	MOVD dst_base+0(FP), R0
	MOVD dst_len+8(FP), R1
	MOVD src_base+24(FP), R2
	MOVD src_len+32(FP), R3
	ADD  R3, R2, R3
	ADD  R1, R0, R1
	SUB  $8, R1, R1

lz4s_snappy_loop:
	CMP   R3, R2
	BHS   lz4s_snappy_corrupt
	CMP   R1, R0
	BHS   lz4s_snappy_dstfull
	MOVBU (R2), R6
	MOVD  R6, R7
	MOVD  R6, R8
	LSR   $0x04, R7, R7
	AND   $0x0f, R8, R8
	CMP   $0xf0, R6
	BLO   lz4s_snappy_ll_end

lz4s_snappy_ll_loop:
	ADD   $1, R2, R2
	CMP   R3, R2
	BHS   lz4s_snappy_corrupt
	MOVBU (R2), R6
	ADD   R6, R7, R7
	CMP   $0xff, R6
	BEQ   lz4s_snappy_ll_loop

lz4s_snappy_ll_end:
	ADD   R7, R2, R6
	ADD   $0x03, R8, R8
	CMP   R3, R6
	BHS   lz4s_snappy_corrupt
	ADD   $1, R2, R2
	ADD   $1, R6, R6
	TST   R7, R7
	BEQ   lz4s_snappy_lits_done
	ADD   R7, R0, R9
	CMP   R1, R9
	BHS   lz4s_snappy_dstfull
	ADD   R7, R5, R5
	SUB   $1, R7, R9
	MOVWU R9, R9
	CMPW  $0x3c, R9
	BLO   one_byte_lz4s_snappy
	CMPW  $0x00000100, R9
	BLO   two_bytes_lz4s_snappy
	CMPW  $0x00010000, R9
	BLO   three_bytes_lz4s_snappy
	CMPW  $0x01000000, R9
	BLO   four_bytes_lz4s_snappy
	MOVD  $0xfc, R16
	MOVB  R16, (R0)
	MOVW  R9, 1(R0)
	ADD   $0x05, R0, R0
	JMP   memmove_long_lz4s_snappy

four_bytes_lz4s_snappy:
	MOVWU R9, R10
	LSRW  $0x10, R10, R10
	MOVD  $0xf8, R16
	MOVB  R16, (R0)
	MOVH  R9, 1(R0)
	MOVB  R10, 3(R0)
	ADD   $0x04, R0, R0
	JMP   memmove_long_lz4s_snappy

three_bytes_lz4s_snappy:
	MOVD $0xf4, R16
	MOVB R16, (R0)
	MOVH R9, 1(R0)
	ADD  $0x03, R0, R0
	JMP  memmove_long_lz4s_snappy

two_bytes_lz4s_snappy:
	MOVD $0xf0, R16
	MOVB R16, (R0)
	MOVB R9, 1(R0)
	ADD  $0x02, R0, R0
	CMPW $0x40, R9
	BLO  memmove_lz4s_snappy
	JMP  memmove_long_lz4s_snappy

one_byte_lz4s_snappy:
	LSLW $0x02, R9, R16
	BFI  $0, R16, $8, R9
	MOVB R9, (R0)
	ADD  $0x01, R0, R0

memmove_lz4s_snappy:
	ADD R7, R0, R9

	// genMemMoveShort
	CMP $0x08, R7
	BLS emit_lit_memmove_lz4s_snappy_memmove_move_8
	CMP $0x10, R7
	BLS emit_lit_memmove_lz4s_snappy_memmove_move_8through16
	CMP $0x20, R7
	BLS emit_lit_memmove_lz4s_snappy_memmove_move_17through32
	JMP emit_lit_memmove_lz4s_snappy_memmove_move_33through64

emit_lit_memmove_lz4s_snappy_memmove_move_8:
	MOVD (R2), R10
	MOVD R10, (R0)
	JMP  memmove_end_copy_lz4s_snappy

emit_lit_memmove_lz4s_snappy_memmove_move_8through16:
	MOVD (R2), R10
	ADD  R7, R2, R15
	MOVD -8(R15), R2
	MOVD R10, (R0)
	ADD  R7, R0, R15
	MOVD R2, -8(R15)
	JMP  memmove_end_copy_lz4s_snappy

emit_lit_memmove_lz4s_snappy_memmove_move_17through32:
	FMOVQ (R2), F0
	ADD   R7, R2, R15
	FMOVQ -16(R15), F1
	FMOVQ F0, (R0)
	ADD   R7, R0, R15
	FMOVQ F1, -16(R15)
	JMP   memmove_end_copy_lz4s_snappy

emit_lit_memmove_lz4s_snappy_memmove_move_33through64:
	FMOVQ (R2), F0
	FMOVQ 16(R2), F1
	ADD   R7, R2, R15
	FMOVQ -32(R15), F2
	ADD   R7, R2, R15
	FMOVQ -16(R15), F3
	FMOVQ F0, (R0)
	FMOVQ F1, 16(R0)
	ADD   R7, R0, R15
	FMOVQ F2, -32(R15)
	ADD   R7, R0, R15
	FMOVQ F3, -16(R15)

memmove_end_copy_lz4s_snappy:
	MOVD R9, R0
	JMP  lz4s_snappy_lits_emit_done

memmove_long_lz4s_snappy:
	ADD R7, R0, R9

	// genMemMoveLong
	MOVD R2, R10
	MOVD R0, R11
	MOVD R7, R12

emit_lit_memmove_long_lz4s_snappylarge_big_loop_back:
	FMOVQ (R10), F0
	FMOVQ 16(R10), F1
	FMOVQ F0, (R11)
	FMOVQ F1, 16(R11)
	ADD   $0x20, R10, R10
	ADD   $0x20, R11, R11
	SUB   $0x20, R12, R12
	CMP   $0x20, R12
	BHS   emit_lit_memmove_long_lz4s_snappylarge_big_loop_back
	ADD   R7, R2, R15
	FMOVQ -32(R15), F0
	ADD   R7, R2, R15
	FMOVQ -16(R15), F1
	ADD   R7, R0, R15
	FMOVQ F0, -32(R15)
	ADD   R7, R0, R15
	FMOVQ F1, -16(R15)
	MOVD  R9, R0

lz4s_snappy_lits_emit_done:
	MOVD R6, R2

lz4s_snappy_lits_done:
	CMP R3, R2
	BNE lz4s_snappy_match
	CMP $0x03, R8
	BEQ lz4s_snappy_done
	JMP lz4s_snappy_corrupt

lz4s_snappy_match:
	CMP   $0x03, R8
	BEQ   lz4s_snappy_loop
	ADD   $2, R2, R6
	CMP   R3, R6
	BHS   lz4s_snappy_corrupt
	MOVHU (R2), R7
	MOVD  R6, R2
	TST   R7, R7
	BEQ   lz4s_snappy_corrupt
	CMP   R5, R7
	BHI   lz4s_snappy_corrupt
	CMP   $0x12, R8
	BNE   lz4s_snappy_ml_done

lz4s_snappy_ml_loop:
	MOVBU (R2), R6
	ADD   $1, R2, R2
	ADD   R6, R8, R8
	CMP   R3, R2
	BHS   lz4s_snappy_corrupt
	CMP   $0xff, R6
	BEQ   lz4s_snappy_ml_loop

lz4s_snappy_ml_done:
	ADD R8, R5, R5

	// emitCopy
two_byte_offset_lz4_s2:
	CMPW  $0x40, R8
	BLS   two_byte_offset_short_lz4_s2
	MOVD  $0xee, R16
	MOVB  R16, (R0)
	MOVH  R7, 1(R0)
	SUB   $60, R8, R8
	MOVWU R8, R8
	ADD   $0x03, R0, R0
	CMP   R1, R0
	BHS   lz4s_snappy_loop
	JMP   two_byte_offset_lz4_s2

two_byte_offset_short_lz4_s2:
	MOVWU R8, R6
	LSLW  $0x02, R6, R6
	CMPW  $0x0c, R8
	BHS   emit_copy_three_lz4_s2
	CMPW  $0x00000800, R7
	BHS   emit_copy_three_lz4_s2
	SUB   $15, R6, R6
	MOVWU R6, R6
	MOVB  R7, 1(R0)
	LSRW  $0x08, R7, R7
	LSLW  $0x05, R7, R7
	ORRW  R7, R6, R6
	MOVB  R6, (R0)
	ADD   $0x02, R0, R0
	JMP   lz4s_snappy_loop

emit_copy_three_lz4_s2:
	SUB   $2, R6, R6
	MOVWU R6, R6
	MOVB  R6, (R0)
	MOVH  R7, 1(R0)
	ADD   $0x03, R0, R0
	JMP   lz4s_snappy_loop

lz4s_snappy_done:
	MOVD dst_base+0(FP), R1
	SUB  R1, R0, R0
	MOVD R5, uncompressed+48(FP)
	MOVD R0, dstUsed+56(FP)
	RET

lz4s_snappy_corrupt:
	MOVD $0, R0
	SUB  $1, R0, R5
	MOVD R5, uncompressed+48(FP)
	RET

lz4s_snappy_dstfull:
	MOVD $0, R0
	SUB  $2, R0, R5
	MOVD R5, uncompressed+48(FP)
	RET
